using Microsoft.EntityFrameworkCore;

// Example Cosmos DB context showing the two EF Core 9 breaking-change fixes.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // FIX 1 – Discriminator property name changed from "Discriminator" to "$type"
        // in EF Core 9. Existing documents already stored a property called
        // "Discriminator", so we must explicitly configure the old name to keep
        // reading them.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");
    }

    // FIX 2 – Synchronous Cosmos DB queries (ToList, First, Single, …) now throw
    // at runtime in EF Core 9.  All queries must be async.
    //
    // BEFORE (EF Core 8 – worked but was deprecated):
    //   var products = db.Products.ToList();
    //
    // AFTER (EF Core 9 – required):
    //   var products = await db.Products.ToListAsync();
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

